package com.example.nailsalon.controller;
import com.example.nailsalon.dto.*; import com.example.nailsalon.entity.User; import com.example.nailsalon.repository.UserRepository; import com.example.nailsalon.security.JwtService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") @Tag(name="Authentication",description="Регистрация и получение JWT. Сначала выполните login, затем используйте токен через Authorize в Swagger.") public class AuthController { private final UserRepository repo; private final PasswordEncoder enc; private final JwtService jwt; public AuthController(UserRepository r,PasswordEncoder e,JwtService j){repo=r;enc=e;jwt=j;}
@Operation(summary="Вход",description="Проверяет логин и пароль и возвращает JWT. Токен действует 24 часа.") @PostMapping("/login") public AuthResponse login(@Valid @RequestBody LoginRequest x){User u=repo.findByLogin(x.login()).orElseThrow(()->new RuntimeException("Неверный логин или пароль")); if(!enc.matches(x.password(),u.getPassword())) throw new RuntimeException("Неверный логин или пароль"); return new AuthResponse(jwt.generate(u.getLogin(),u.getRole()),u.getLogin(),u.getRole());}
@Operation(summary="Регистрация",description="Создаёт обычного пользователя USER. Пароль сохраняется в BCrypt.") @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) public User register(@Valid @RequestBody User u){if(repo.findByLogin(u.getLogin()).isPresent()) throw new IllegalArgumentException("Логин уже занят"); u.setRole("USER"); u.setPassword(enc.encode(u.getPassword())); return repo.save(u);}
}
